const requeueTask = `-- name: RequeueTask :execrows
UPDATE tasks
SET status = 'pending', worker_id = NULL, assigned_at = NULL, started_at = NULL,
    assignment_epoch = assignment_epoch + 1
WHERE id = $1
  AND assignment_epoch = $2
  AND worker_id = $3
  AND status = 'dispatched'
`

type RequeueTaskParams struct {
	ID              pgtype.UUID `json:"id"`
	AssignmentEpoch int32       `json:"assignment_epoch"`
	WorkerID        pgtype.UUID `json:"worker_id"`
}

// Revert a single task from 'dispatched' back to 'pending', on the SAME FOUR
// predicates as RequeueTaskByID: id (which row), assignment_epoch (is the
// caller's view still current), worker_id (is this the caller's own
// assignment), status (is the row still dispatched at all).
//
// THIS IS THE SECOND OF TWO STATEMENTS THAT HAD THE UNFENCED SHAPE, AND BOTH ARE
// NOW FENCED. Recorded here because
// bug-2026-08-20-requeuetaskbyid-has-no-epoch-or-assignee-fence says
// RequeueTaskByID was "the only requeue statement in the tree whose WHERE clause
// names nothing but the task id and a status allow-list". That was FALSE when it
// was written: this statement, three statements away in this same file, had
// exactly that WHERE. The sweep is finished - do not re-derive it.
//
// Used when the registry send fails after the task has been claimed
// (internal/scheduler/dispatch.go).
//
// WHICH SEND FAILURE ACTUALLY LEAVES A WINDOW. An earlier version of this
// comment said the window is reachable because "a disconnected worker is what
// arms its own grace timer". THAT WAS WRONG and it is written down so nobody
// reinstates it: the two halves cannot co-occur. If the worker is gone from the
// registry, Registry.Send returns before workerSender.Send is ever reached, so
// there is no window at all. If the worker DISCONNECTED, sender.closed is closed
// when the send loop returns, so a blocked Send takes `case <-sender.closed` and
// returns IMMEDIATELY - and teardownConnection closes the sender before it calls
// h.grace.Start, so this requeue is unblocked strictly before the grace timer is
// even armed, which then waits its full window on top.
//
// The only branch that burns the 5s sendTimeout is `case <-timeout.C` on a full
// 64-slot queue, which requires the send loop alive inside stream.Send: the
// worker is WEDGED BUT STILL REGISTERED, online, and has no grace timer armed.
// Two mechanisms reach the race from there, and neither involves a grace timer:
//   - ADMIN DISABLE. handleDisableWorker (internal/api/workers.go) calls
//     RequeueWorkerTasks, which returns T to 'pending' and bumps the epoch; the
//     dispatcher re-claims it for W2; the still-wedged goroutine then fires this
//     statement on its stale snapshot.
//   - A SECOND Connect FROM THE SAME AGENT while the first stream is wedged.
//     Nothing serializes Connect per worker. The new stream's reconcile sees T
//     as 'dispatched', the agent does not report it (it never received it), the
//     SIBLING statement requeues it, triggerDispatch fires, W2 gets it, and the
//     wedged goroutine tears it off. No admin, no grace timer.
//
// In both, a fresh assignment is 'dispatched', so on the id and the status alone
// this statement MATCHED and tore a live task off W2 - duplicate execution with
// no log line anywhere, the same end state as its sibling.
//
// THE STATUS PREDICATE STAYS 'dispatched' ONLY, pinned by
// TestRequeueTask_RunningTaskIsNotRequeuedByTheSendFailurePath. Do not widen it
// to include 'running' for symmetry with RequeueTaskByID: at this caller's own
// (epoch, worker) pair the task cannot have reported running - for any agent
// that only reports epochs it was actually dispatched - because the Send that
// would have delivered the dispatch is the thing that just failed.
// BE PRECISE ABOUT WHAT THAT PROOF COVERS, because the next reader will use this
// paragraph to decide whether the epoch is coordinator-side or agent-side.
// workerSender.Send has exactly TWO error values, ErrWorkerDisconnected and
// ErrSendTimeout, and both are select branches mutually exclusive with the
// enqueue, so on either the DispatchTask was never queued, never written to the
// stream, and never seen by the agent. The third case, "worker is not
// connected", is Registry.Send's own error, returned before workerSender.Send is
// reached - so it never enqueues either, but it is NOT a select branch and the
// mutual-exclusion argument does not cover it. The residual gap is that
// handleTaskStatus takes the epoch OFF THE WIRE and compares it to the DB's
// current value, so a connected agent that is the current assignee could report
// 'running' at an epoch it was never dispatched. That needs a task id it would
// not otherwise know, and the watchdog bounds it, so the decision here is
// unaffected - but it is why this says "cannot for a well-behaved agent" rather
// than "cannot".
//
// The worker_id comparison must stay a plain `=`, never IS NOT DISTINCT FROM:
// tasks.worker_id is NULLABLE and a zero-value pgtype.UUID binds SQL NULL, so
// `=` makes a caller that lost its identity fail CLOSED instead of matching an
// unassigned row. TestRequeueTask_NullWorkerIDDoesNotMatchANullArgument PLANTS
// the row it tests, because the status predicate makes that state unreachable
// through production statements - a second guarantee behind the first, not a
// reason to relax the first.
//
// Bumps assignment_epoch so a late update from the prior assignment is fenced
// out. The bump is inside the same UPDATE as the WHERE, so it happens only for
// rows that actually matched - the "conditionally end the assignment" branch of
// the epoch fence, never an unconditional bump.
//
// :execrows, not :exec, matching its sibling, so the fence tests can assert a
// rowcount rather than infer rejection from row state. THE CALLER DISCARDS THE
// COUNT DELIBERATELY and that is not copied reasoning: unlike the reconcile
// path, this site is in the dispatcher and DOES have a log budget - it already
// logs the send failure unconditionally on the line above. A second line saying
// the requeue moved nothing would add no information that line does not already
// carry, and would double the volume of an already-unbudgeted path. Zero rows is
// the CORRECT outcome anyway: another writer ended this assignment first, and
// dispatchOne returns false either way.
//
//	UPDATE tasks
//	SET status = 'pending', worker_id = NULL, assigned_at = NULL, started_at = NULL,
//	    assignment_epoch = assignment_epoch + 1
//	WHERE id = $1
//	  AND assignment_epoch = $2
//	  AND worker_id = $3
//	  AND status = 'dispatched'
func (q *Queries) RequeueTask(ctx context.Context, arg RequeueTaskParams) (int64, error) {
	result, err := q.db.Exec(ctx, requeueTask, arg.ID, arg.AssignmentEpoch, arg.WorkerID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const requeueTaskByID = `-- name: RequeueTaskByID :execrows
UPDATE tasks
SET status = 'pending',
    worker_id = NULL,
    assigned_at = NULL,
    started_at = NULL,
    finished_at = NULL,
    assignment_epoch = assignment_epoch + 1
WHERE id = $1
  AND assignment_epoch = $2
  AND worker_id = $3
  AND status IN ('dispatched', 'running')
`

type RequeueTaskByIDParams struct {
	ID              pgtype.UUID `json:"id"`
	AssignmentEpoch int32       `json:"assignment_epoch"`
	WorkerID        pgtype.UUID `json:"worker_id"`
}

// Revert a single ASSIGNED task back to 'pending', on FOUR predicates. Each
// answers a different question, none is redundant with the others, and none may
// be deleted:
//   - id               - WHICH ROW.
//   - assignment_epoch - IS THE CALLER'S VIEW STILL CURRENT? (currency)
//   - worker_id        - IS THIS THE CALLER'S OWN ASSIGNMENT? (identity)
//   - status           - IS THE ROW STILL ASSIGNED AT ALL, i.e. not terminal.
//
// Used by the reconcile path when the coordinator has a task assigned that the
// agent didn't report as running (internal/worker/handler.go,
// reconcileRunningTasks). Candidates come from GetActiveTasksForWorker, which
// reads the id and the epoch under one snapshot; the worker id is the
// connection's own, resolved at registration and never taken from the wire.
//
// WHAT THE STATUS ALLOW-LIST ALONE DOES NOT COVER, and what this comment used to
// claim it did. It called the allow-list "the backstop for the window between
// that read and this write". It is the backstop for exactly ONE thing that can
// happen in that window - the task FINISHING - and it was silent about the more
// damaging one: the task being requeued by somebody else and RE-DISPATCHED to a
// second worker. A fresh assignment is 'dispatched', which the allow-list
// admits, so a reconcile walking a stale snapshot used to tear a live task off a
// worker that had only just been given it, bump the epoch, and leave the first
// agent's subprocess running with every message it sent afterwards fenced out in
// silence - duplicate execution, with no log line anywhere. Two overlapping
// registrations of one worker reach that, and so does a grace timer firing just
// before finishRegister cancels it. See
// bug-2026-08-20-requeuetaskbyid-has-no-epoch-or-assignee-fence.
//
// The epoch predicate closes it: a re-dispatch bumps assignment_epoch, so the
// stale caller's epoch no longer matches and zero rows move. The worker
// predicate closes it independently AND closes what the epoch cannot, because
// THE EPOCH ESTABLISHES CURRENCY, NOT IDENTITY: a matching epoch proves the
// caller's generation is current, never that the caller was entitled to end it.
// Keep all four.
//
// The worker_id comparison must stay a plain `=`, never IS NOT DISTINCT FROM,
// for exactly the reason spelled out at UpdateTaskStatus: tasks.worker_id is
// NULLABLE and a zero-value pgtype.UUID binds SQL NULL, so `=` makes a caller
// that lost its identity fail CLOSED instead of matching an unassigned row. Do
// not "fix the NULL bug" here either. The status allow-list happens to make that
// state unreachable today - a row with a NULL worker_id is 'pending' or terminal,
// and neither is admitted - which is why
// TestRequeueTaskByID_NullWorkerIDDoesNotMatchANullArgument has to PLANT the row
// it tests. That is a second guarantee behind the first, not a reason to relax
// the first.
//
// Bumps assignment_epoch so a late update from the prior assignment is fenced
// out. The bump is inside the same UPDATE as the WHERE, so it happens only for
// rows that actually matched - the "conditionally end the assignment" branch of
// the epoch fence, never an unconditional bump.
//
// :execrows, not :exec, so the caller counts MATCHES rather than ATTEMPTS. Zero
// rows is a NORMAL, CORRECT outcome here - it means another writer ended this
// assignment first - and it is deliberately neither logged nor counted: this
// runs inside finishRegister, ahead of the connection's ingestLogLimiter, so the
// site has no budget to spend, and Handler.Metrics is a utilization ring buffer
// that is not even Activated yet at that point. The general gap is tracked by
// idea-2026-08-14-tasklog-fence-rejection-is-unobservable; do not close it here
// with a one-off.
//
// assigned_at is nulled alongside worker_id. Every statement in this file that
// nulls worker_id does the same, and ClaimTaskForWorker is the only statement
// that sets either.
// THE CLAIM IS ONE-DIRECTIONAL, and it is worth being precise because the
// tempting shorthand is false: `assigned_at IS NULL` means the row holds no
// assignment, but the CONVERSE DOES NOT HOLD. UpdateTaskStatus deliberately
// writes neither column, so every `done`, every `timed_out` and every `failed`
// row that got there through it still carries a non-NULL assigned_at - which is
// correct, since the assignment must outlive the task for the trailing-log
// flush. (CancelJobTasks nulls it, so the column does not even mean one
// consistent thing across terminal rows.) Anything that means "CURRENTLY
// assigned" must say so with the status predicate, exactly as
// ListOverdueAssignedTasks does; a query keying on `assigned_at IS NOT NULL`
// alone would select every task ever dispatched.
//
//	UPDATE tasks
//	SET status = 'pending',
//	    worker_id = NULL,
//	    assigned_at = NULL,
//	    started_at = NULL,
//	    finished_at = NULL,
//	    assignment_epoch = assignment_epoch + 1
//	WHERE id = $1
//	  AND assignment_epoch = $2
//	  AND worker_id = $3
//	  AND status IN ('dispatched', 'running')
func (q *Queries) RequeueTaskByID(ctx context.Context, arg RequeueTaskByIDParams) (int64, error) {
	result, err := q.db.Exec(ctx, requeueTaskByID, arg.ID, arg.AssignmentEpoch, arg.WorkerID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const requeueWorkerTasks = `-- name: RequeueWorkerTasks :many
UPDATE tasks
SET status = 'pending',
    worker_id = NULL,
    assigned_at = NULL,
    started_at = NULL,
    assignment_epoch = assignment_epoch + 1
WHERE worker_id = $1 AND status IN ('dispatched', 'running')
RETURNING id
`

// Re-queue dispatched/running tasks for a worker that has disconnected or is
// being disabled. Bumps assignment_epoch so a stale status update or log chunk
// from the (possibly still-connected) agent is rejected by the epoch fence.
// Returns the affected task ids; the disable path uses them to send cancels,
// the disconnect/grace paths discard them.
//
//	UPDATE tasks
//	SET status = 'pending',
//	    worker_id = NULL,
//	    assigned_at = NULL,
//	    started_at = NULL,
//	    assignment_epoch = assignment_epoch + 1
//	WHERE worker_id = $1 AND status IN ('dispatched', 'running')
//	RETURNING id
func (q *Queries) RequeueWorkerTasks(ctx context.Context, workerID pgtype.UUID) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, requeueWorkerTasks, workerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const requeueWorkerTasksIfEpoch = `-- name: RequeueWorkerTasksIfEpoch :many
UPDATE tasks
SET status = 'pending',
    worker_id = NULL,
    assigned_at = NULL,
    started_at = NULL,
    assignment_epoch = assignment_epoch + 1
WHERE worker_id = $1 AND status IN ('dispatched', 'running')
  AND EXISTS (SELECT 1 FROM workers w WHERE w.id = $1 AND w.connection_epoch = $2)
RETURNING id
`

type RequeueWorkerTasksIfEpochParams struct {
	WorkerID        pgtype.UUID `json:"worker_id"`
	ConnectionEpoch int32       `json:"connection_epoch"`
}

// Re-queue dispatched/running tasks for a disconnected worker, but only if the
// worker's connection_epoch still matches the epoch the caller owned. If a fresh
// connection has superseded it, the EXISTS guard fails and zero tasks move.
// Bumps assignment_epoch on each requeued task (task-level fence preserved).
//
//	UPDATE tasks
//	SET status = 'pending',
//	    worker_id = NULL,
//	    assigned_at = NULL,
//	    started_at = NULL,
//	    assignment_epoch = assignment_epoch + 1
//	WHERE worker_id = $1 AND status IN ('dispatched', 'running')
//	  AND EXISTS (SELECT 1 FROM workers w WHERE w.id = $1 AND w.connection_epoch = $2)
//	RETURNING id
func (q *Queries) RequeueWorkerTasksIfEpoch(ctx context.Context, arg RequeueWorkerTasksIfEpochParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, requeueWorkerTasksIfEpoch, arg.WorkerID, arg.ConnectionEpoch)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const retryJobTasks = `-- name: RetryJobTasks :many
WITH RECURSIVE selected AS (
    SELECT id FROM tasks
    WHERE job_id = $1
      AND (status IN ('failed','timed_out')
           OR ($2::bool AND status = 'done'))
), descendants AS (
    SELECT td.task_id AS id
    FROM task_dependencies td
    WHERE td.depends_on_task_id IN (SELECT id FROM selected)
  UNION
    SELECT td.task_id
    FROM task_dependencies td
    JOIN descendants dd ON dd.id = td.depends_on_task_id
)
UPDATE tasks t
SET status           = 'pending',
    worker_id        = NULL,
    assigned_at      = NULL,
    started_at       = NULL,
    finished_at      = NULL,
    retry_count      = 0,
    assignment_epoch = t.assignment_epoch + 1
WHERE t.job_id = $1
  AND (t.status IN ('failed','timed_out')
       OR ($2::bool AND t.status = 'done'))
  AND NOT EXISTS (
        SELECT 1
        FROM descendants d
        JOIN tasks dep ON dep.id = d.id
        WHERE dep.status <> 'pending'
          AND d.id NOT IN (SELECT id FROM selected)
      )
RETURNING t.id
`

type RetryJobTasksParams struct {
	JobID       pgtype.UUID `json:"job_id"`
	IncludeDone bool        `json:"include_done"`
}

// OPERATOR re-run of a terminal job's tasks: the analogue of RequeueTaskByID,
// and explicitly NOT of IncrementTaskRetryCount. Its preconditions are the exact
// inverse of that statement's: it reopens tasks that ARE terminal and has no
// worker identity to bind, so that statement's status and worker predicates
// would reject every call. See the note at IncrementTaskRetryCount.
//
// Epoch fence: this satisfies the invariant's "conditionally end the assignment"
// branch. The bump is inside the same UPDATE as the WHERE, so it happens only
// for rows that actually matched - never unconditionally, which would satisfy
// the rule vacuously.
//
// No fence on a CALLER epoch and no worker predicate, deliberately, for the same
// reason CancelJobTasks has none: an operator has no generation and no worker
// identity to prove. What replaces the identity predicate is the status
// allow-list. A terminal row has no live assignment, so there is no agent to
// evict; a `dispatched` or `running` task is unreachable by this statement in
// either mode.
//
// THAT ARGUMENT HAS A DEPENDENCY, and it is not visible from this WHERE clause:
// it holds because of WHO writes each terminal status, not because the statuses
// are terminal. `timed_out` has exactly one writer, and it is the assignee
// itself: the agent gives each task's subprocess a context deadline built from
// timeout_sec (internal/agent/runner.go, newRunner), and when cmd.Wait returns
// with ctx.Err() == context.DeadlineExceeded - so the process is already dead
// and its proctree already cleaned up - the runner reports TASK_STATUS_TIMED_OUT
// as its final status. internal/worker/handler.go maps that to 'timed_out' and
// writes it through UpdateTaskStatus, fenced on the sender's epoch and worker
// id. So a `timed_out` row, like a `failed` or `done` one, records an agent
// saying "I am finished with this", after it stopped executing. There is nothing
// left to evict.
// What would break this is a SERVER-SIDE watchdog: something that stamps
// `timed_out` on a task the agent is still happily running, because the row
// looks stale from the coordinator's side. That row would be terminal AND still
// executing, and this statement would become a duplicate-execution primitive -
// the retry reopens it, the dispatcher hands it to a second worker, and the
// first agent's eventual completion is fenced out by the epoch bump, so nothing
// reports the collision.
// THAT WATCHDOG NOW EXISTS, so read the paragraph above as history: `timed_out`
// has TWO writers. The assignee itself (handleTaskStatus, after its subprocess
// is already dead), and the coordinator watchdog
// (internal/scheduler/watchdog.go), which stamps `timed_out` on a task whose
// agent may still be happily running it. So a `timed_out` row selected here MAY
// be terminal and still executing, and this statement can reopen it for a second
// worker while the first agent's eventual completion is fenced out silently.
// THAT HAZARD IS NOT NEW WITH THE WATCHDOG, which is why it did not block it:
// CancelJobTasks already stamps `failed` on live `dispatched`/`running`
// assignments and handleCancelJob mitigates with a best-effort
// sendCancelSignals. The watchdog adopts the identical mitigation - it sends
// CancelTask (force=false) to every swept task's worker after the write.
// The residual is bounded by: the sweep fires only long past the deadline plus a
// generous margin, the reopen is OPERATOR-GATED (nothing retries a swept task
// automatically), and the original agent's own completion is fenced out.
// Eliminating it entirely needs a per-assignment fencing token at the agent.
// That is a NAMED NON-GOAL, not a plan.
//
// THE STATUS ALLOW-LIST MUST STAY IN THIS WHERE CLAUSE, on tasks' own columns.
// Do not "simplify" it to `t.id IN (SELECT id FROM selected)`. Under READ
// COMMITTED a blocked UPDATE re-evaluates its ROW-LEVEL qual against the updated
// tuple (EvalPlanQual); it does not re-execute CTEs. With the status test only
// in the CTE, a second concurrent retry re-updates rows the first already
// reopened and double-bumps assignment_epoch.
// This is pinned by
// TestRetryJobTasks_RowLevelPredicate_ConcurrentSecondRetryDoesNotDoubleBumpEpoch.
// This is the multi-row analogue of the reasoning in IncrementTaskRetryCount's
// `assignment_epoch` note.
//
// The allow-list is an ALLOW-LIST for the same reason UpdateTaskStatus's is:
// a new status must be un-retryable until somebody decides otherwise.
// TestTasksStatusVocabularyIsExactly names this statement.
//
// The dependents guard is all-or-nothing by construction: the NOT EXISTS is
// uncorrelated, so it is true for every row or for none. Partial application is
// unrepresentable, which is what keeps a retry from stranding a reopened task
// behind a dependency that stayed terminal. `dep.status <> 'pending'` is a
// NEGATION on purpose: this predicate authorizes BLOCKING, so failing closed
// means blocking on any status added later. The allow-list spelling would fail
// open here. `pending` is the only status that proves a dependent was never
// claimed (ClaimTaskForWorker requires status='pending').
//
// A dependent that is itself in `selected` does not block: FailDependentTasks
// cascade-fails a failing task's pending dependents, so on any healthy failed
// job every selected task has failed dependents. Without the NOT IN (selected)
// exclusion this statement would refuse every ordinary retry.
//
// retry_count = 0 is a stated decision, not a copied SET clause: its one
// behavioral consumer is `terminal && task.RetryCount < task.Retries` in
// handleTaskStatus (internal/worker/handler.go), so leaving the counter at its
// exhausted value hands the operator a re-run with zero agent retries - exactly
// what they pressed Retry to escape.
//
// UNION (not UNION ALL) in the recursive term dedupes, so the walk terminates
// even if a cycle is ever introduced. Edges are intra-job by construction
// (jobcreate resolves depends_on within one spec).
//
//	WITH RECURSIVE selected AS (
//	    SELECT id FROM tasks
//	    WHERE job_id = $1
//	      AND (status IN ('failed','timed_out')
//	           OR ($2::bool AND status = 'done'))
//	), descendants AS (
//	    SELECT td.task_id AS id
//	    FROM task_dependencies td
//	    WHERE td.depends_on_task_id IN (SELECT id FROM selected)
//	  UNION
//	    SELECT td.task_id
//	    FROM task_dependencies td
//	    JOIN descendants dd ON dd.id = td.depends_on_task_id
//	)
//	UPDATE tasks t
//	SET status           = 'pending',
//	    worker_id        = NULL,
//	    assigned_at      = NULL,
//	    started_at       = NULL,
//	    finished_at      = NULL,
//	    retry_count      = 0,
//	    assignment_epoch = t.assignment_epoch + 1
//	WHERE t.job_id = $1
//	  AND (t.status IN ('failed','timed_out')
//	       OR ($2::bool AND t.status = 'done'))
//	  AND NOT EXISTS (
//	        SELECT 1
//	        FROM descendants d
//	        JOIN tasks dep ON dep.id = d.id
//	        WHERE dep.status <> 'pending'
//	          AND d.id NOT IN (SELECT id FROM selected)
//	      )
//	RETURNING t.id
func (q *Queries) RetryJobTasks(ctx context.Context, arg RetryJobTasksParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, retryJobTasks, arg.JobID, arg.IncludeDone)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var id pgtype.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

