const updateTaskStatus = `-- name: UpdateTaskStatus :one
UPDATE tasks
SET status = $1,
    started_at = COALESCE(started_at, $2),
    finished_at = $3
WHERE id = $4
  AND assignment_epoch = $5
  AND worker_id = $6
  AND status IN ('pending', 'dispatched', 'running')
RETURNING id, job_id, name, env, requires, timeout_seconds, retries, retry_count, status, worker_id, started_at, finished_at, created_at, assignment_epoch, source, commands, assigned_at
`

type UpdateTaskStatusParams struct {
	Status          string             `json:"status"`
	StartedAt       pgtype.Timestamptz `json:"started_at"`
	FinishedAt      pgtype.Timestamptz `json:"finished_at"`
	ID              pgtype.UUID        `json:"id"`
	AssignmentEpoch int32              `json:"assignment_epoch"`
	WorkerID        pgtype.UUID        `json:"worker_id"`
}

// Updates a task's status only if ALL THREE fence predicates hold: the task is
// currently assigned to the caller's worker (identity), the caller's epoch
// matches the current assignment (currency), and the task is not already
// terminal (one-way status machine, see the terminality paragraph below). The
// epoch answers "is this generation current"; the worker id answers "are you who
// you say you are"; the status answers "is this task still writable at all".
// None substitutes for another - do not delete any of them.
// This statement no longer writes worker_id; the argument is a fence, not a
// value. That makes the old contract ("callers MUST pass the task's existing
// worker_id through, because clearing it would strand a live agent forever")
// structural rather than documented: the statement can no longer clear the
// column at all. It does not bump assignment_epoch either, so a terminal task
// keeps its assignee and trailing log chunks from the agent that just finished
// still pass AppendTaskLog's fence.
// started_at is WRITE-ONCE PER ASSIGNMENT, via COALESCE, and that is a fence in
// its own right rather than a tidiness choice. It closes a hole in BOTH
// directions:
//   - The agent could reset the coordinator's own clock. handleTaskStatus stamps
//     startedAt = time.Now() on EVERY TASK_STATUS_RUNNING, this allow-list admits
//     'running', and both other predicates pass trivially for the assignee - it
//     is its own worker id, at its own epoch. AgentMessage_TaskStatus is itself
//     unbudgeted - ingestLogLimiter bounds LOG LINES, never messages, and it has
//     never gated this dispatch - so an agent with timeout_seconds=60 emitting
//     one RUNNING every ten minutes kept
//     `now - started_at` under the watchdog's execution bound forever. The VALUE
//     was always a relay-server clock; the TRIGGER was the agent's, and that is
//     what a bound measured from this column cannot survive. "A timeout the agent
//     is free not to honour is a suggestion, not a timeout" applies to the
//     coordinator's own timeout too.
//   - The coordinator could clobber a start time it never read. The watchdog binds
//     the started_at its scan read; for a `dispatched` row that is NULL. If the
//     agent reports running inside the scan-to-write window - a transition that
//     legitimately passes all three fences, since 'running' does not bump the
//     epoch - the stale NULL used to overwrite the real value, leaving a
//     `timed_out` row with a finished_at and no start time.
//
// COALESCE makes both a no-op. NO CALLER NEEDS TO CLEAR started_at THROUGH THIS
// STATEMENT: every path that legitimately needs a fresh one returns the task to
// `pending` and NULLs the column in its own SET clause first - RequeueTask,
// RequeueTaskByID, RequeueWorkerTasks, RequeueWorkerTasksIfEpoch,
// IncrementTaskRetryCount, RetryJobTasks. CancelJobTasks keeps it deliberately: a
// cancelled task that really did start has a real start time. If a future caller
// needs to clear it, give that caller its own statement; do not delete the
// COALESCE. TestUpdateTaskStatus_RunningDoesNotRestampStartedAt and
// TestUpdateTaskStatus_DoesNotClobberAStartedAtItDidNotRead pin both directions.
// The worker_id comparison must stay a plain `=`. tasks.worker_id is NULLABLE,
// so `=` makes a never-claimed task reject every update, which is the hole this
// predicate closes, and makes a caller that lost its identity (a zero-value
// pgtype.UUID binds SQL NULL) fail closed. `IS NOT DISTINCT FROM` would let a
// NULL parameter match a NULL worker_id and re-open it. Do not "fix the NULL
// bug" here.
// A task's status machine is one-way into a terminal state. The status
// predicate makes that structural: an already-finished task cannot be written
// again, so a second terminal message from its own assignee at the same epoch -
// which both other predicates legitimately accept, because a terminal
// transition neither bumps the epoch nor clears worker_id - cannot flip a `done`
// task to `failed` and cascade FailDependentTasks across its still-pending
// downstream.
// CANONICAL STATEMENT OF THE TERMINALITY RULE. IncrementTaskRetryCount carries
// the identical predicate and cross-references this paragraph rather than
// repeating it; change both or neither.
//   - It is an ALLOW-LIST, not the complement deny-list, and that choice is
//     load-bearing even though the two are exactly equivalent against today's
//     vocabulary (migration 000019's tasks_status_check pins it to the six
//     values pending/dispatched/running/done/failed/timed_out). A deny-list
//     fails OPEN on the next status added: a task-level `cancelled` is a
//     plausible near-term addition, because CancelJobTasks currently squashes
//     cancellation onto `failed`, and under `NOT IN (terminal)` such a status
//     would be silently writable and would re-open the resurrection this
//     predicate closes. The allow-list fails closed instead - a new status is
//     unwritable until somebody decides it should be. Every other status
//     predicate in this file is already an allow-list; these two now match.
//   - The set is the complement of the terminal set RecomputeJobStatus counts
//     (see the RecomputeJobStatus statement in jobs.sql - by name, because line
//     numbers rot); keep the two in lockstep. TestTasksStatusVocabularyIsExactly
//     goes RED when the vocabulary changes and names every site to revisit.
//   - The fix for the duplicate-terminal case is this predicate and NOT an epoch
//     bump on terminal transitions: the assignment must survive completion so a
//     trailing log chunk from the agent that just finished still passes
//     AppendTaskLog's fence. See
//     TestUpdateTaskStatus_TerminalTransitionDoesNotEndTheAssignmentSoTrailingLogsStillPersist.
//
// Dispatcher.failClaimedTask's target is `dispatched` by construction
// (ClaimTaskForWorker requires `status='pending'`), so this predicate is
// tautological there, exactly like the worker predicate above and for the same
// reason: one statement with no exceptions to remember.
// All THREE callers are fenced by the same statement deliberately;
// Dispatcher.failClaimedTask passes claimed.WorkerID from ClaimTaskForWorker,
// and scheduler.Watchdog passes the worker_id and assignment_epoch off the row
// its own scan just returned - so in both the worker predicate is tautological
// by design, exactly as this comment goes on to describe, while the EPOCH
// predicate is the real TOCTOU guard and is not tautological in either. The
// watchdog is why this slice added no new statement that writes tasks.status.
// For why that beats a second un-fenced query or a "skip the check" sentinel,
// see
// docs/superpowers/specs/2026-08-12-taskstatus-update-assignee-fence.md.
// The fence binds a WORKER identity, not a connection: two concurrent streams
// registered for the same worker row both satisfy it. That matches AppendTaskLog
// and is what keeps reconnect-within-the-grace-window working, so it is not a
// regression - but do not read this predicate as connection-scoped.
// handleTaskStatus's retry branch calls IncrementTaskRetryCount and returns
// before ever reaching this statement, so this predicate never sees that path.
// That statement carries these same three predicates plus a FOURTH on the retry
// budget (`retry_count < retries`), so the two together cover every production
// writer. The Go identity gate in handleTaskStatus stays
// as well: after the retry statement was fenced it is no longer the correctness
// control, but it still answers a different question ("may this sender drive
// this task's status machine at all") one round trip earlier. It does NOT save
// a log line - handleTaskStatus drops pgx.ErrNoRows from both write sites
// without logging, and COUNTS it instead: h.statusFence records the rejection,
// classified by whether this row was still writable when GetTask read it, and
// GET /v1/server/counters publishes the three reasons as task_status_fence.
// THE COUNTER IS WHY THE GO GATE NOW MATTERS BEYOND ITS ROUND TRIP: it is what
// keeps those numbers attributable to the task's own assignee, so a registered
// peer cannot inflate conflicting_total by naming tasks it does not own. The
// round-trip saving is still one statement instead of two, since
// GetTask has already run before the gate. Do not delete either as redundant
// with the other, but do not oversell the Go one either.
//
//	UPDATE tasks
//	SET status = $1,
//	    started_at = COALESCE(started_at, $2),
//	    finished_at = $3
//	WHERE id = $4
//	  AND assignment_epoch = $5
//	  AND worker_id = $6
//	  AND status IN ('pending', 'dispatched', 'running')
//	RETURNING id, job_id, name, env, requires, timeout_seconds, retries, retry_count, status, worker_id, started_at, finished_at, created_at, assignment_epoch, source, commands, assigned_at
func (q *Queries) UpdateTaskStatus(ctx context.Context, arg UpdateTaskStatusParams) (Task, error) {
	row := q.db.QueryRow(ctx, updateTaskStatus,
		arg.Status,
		arg.StartedAt,
		arg.FinishedAt,
		arg.ID,
		arg.AssignmentEpoch,
		arg.WorkerID,
	)
	var i Task
	err := row.Scan(
		&i.ID,
		&i.JobID,
		&i.Name,
		&i.Env,
		&i.Requires,
		&i.TimeoutSeconds,
		&i.Retries,
		&i.RetryCount,
		&i.Status,
		&i.WorkerID,
		&i.StartedAt,
		&i.FinishedAt,
		&i.CreatedAt,
		&i.AssignmentEpoch,
		&i.Source,
		&i.Commands,
		&i.AssignedAt,
	)
	return i, err
}

const updateTaskStatusEpoch = `-- name: UpdateTaskStatusEpoch :one
UPDATE tasks
SET status = $1
WHERE id = $2 AND assignment_epoch = $3
RETURNING id, job_id, name, env, requires, timeout_seconds, retries, retry_count, status, worker_id, started_at, finished_at, created_at, assignment_epoch, source, commands, assigned_at
`

type UpdateTaskStatusEpochParams struct {
	Status string      `json:"status"`
	ID     pgtype.UUID `json:"id"`
	Epoch  int32       `json:"epoch"`
}

// TEST-ONLY. No assignee fence - this is the one remaining writer to
// tasks.status that does not demand a worker id, so it fences currency without
// identity and a never-claimed task at epoch 0 accepts a write from anybody.
// Do NOT call this from production code: use UpdateTaskStatus, which fences on
// both. It has no production callers today and must not gain one.
// Updates a task's status only if the caller's epoch matches the current
// assignment_epoch. Returns pgx.ErrNoRows if the epoch is stale.
//
//	UPDATE tasks
//	SET status = $1
//	WHERE id = $2 AND assignment_epoch = $3
//	RETURNING id, job_id, name, env, requires, timeout_seconds, retries, retry_count, status, worker_id, started_at, finished_at, created_at, assignment_epoch, source, commands, assigned_at
func (q *Queries) UpdateTaskStatusEpoch(ctx context.Context, arg UpdateTaskStatusEpochParams) (Task, error) {
	row := q.db.QueryRow(ctx, updateTaskStatusEpoch, arg.Status, arg.ID, arg.Epoch)
	var i Task
	err := row.Scan(
		&i.ID,
		&i.JobID,
		&i.Name,
		&i.Env,
		&i.Requires,
		&i.TimeoutSeconds,
		&i.Retries,
		&i.RetryCount,
		&i.Status,
		&i.WorkerID,
		&i.StartedAt,
		&i.FinishedAt,
		&i.CreatedAt,
		&i.AssignmentEpoch,
		&i.Source,
		&i.Commands,
		&i.AssignedAt,
	)
	return i, err
}
